CREATE TABLE IF NOT EXISTS gm_rc_sync_runs (slot_start TEXT PRIMARY KEY, status TEXT NOT NULL CHECK(status IN ('RUNNING','DONE','PARTIAL','FAILED')), started_at TEXT NOT NULL, updated_at TEXT NOT NULL, finished_at TEXT, scanned INTEGER NOT NULL DEFAULT 0 CHECK(scanned>=0 AND scanned<=20), signals_written INTEGER NOT NULL DEFAULT 0 CHECK(signals_written>=0 AND signals_written<=200), no_proof INTEGER NOT NULL DEFAULT 0 CHECK(no_proof>=0 AND no_proof<=20), failures INTEGER NOT NULL DEFAULT 0 CHECK(failures>=0 AND failures<=20), last_error_code TEXT); CREATE INDEX IF NOT EXISTS gm_rc_sync_runs_status ON gm_rc_sync_runs(status,slot_start);
